sections.css:
.esa-breadcrumbs {
  --_crumb-font-size: var(--type-size-200, 0.875rem);
  --_crumb-link-color: var(--breadcrumbs-link-color, #43608a);
  --_crumb-link-hover: var(--breadcrumbs-link-hover, #39506f);
  --_crumb-current-color: var(--color-text-primary, #171717);
  --_crumb-separator-color: var(--breadcrumbs-separator-color, #737373);
  --_crumb-gap: var(--spacing-200, 8px);
  display: block;
}
.esa-breadcrumbs--sm {
  --_crumb-font-size: var(--type-size-150, 0.75rem);
}
.esa-breadcrumbs__list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--_crumb-gap);
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: var(--_crumb-font-size);
}
.esa-breadcrumbs__item {
  display: flex;
  align-items: center;
  gap: var(--_crumb-gap);
}
.esa-breadcrumbs__link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-link-color);
  text-decoration: none;
}
.esa-breadcrumbs__icon {
  display: inline-flex;
  align-items: center;
}
.esa-breadcrumbs__separator {
  flex-shrink: 0;
  color: var(--_crumb-separator-color);
}
.esa-breadcrumbs__current {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-current-color);
  font-weight: var(--font-weight-medium, 500);
}
.scenario-header__glyph {
  display: inline-flex;
  color: var(--color-primary, #235069);
}
.scenario-header__glyph svg {
  width: 26px;
  height: 26px;
}
.scenario-header__h1 {
  margin: 0;
  font-family:
    Google Sans Flex,
    sans-serif;
  font-size: var(--type-size-600, 1.875rem);
  font-weight: 500;
  line-height: 1.1;
  color: var(--color-primary, #235069);
}
.scenario-header__switcher {
  min-width: 20rem;
}
.scenario-header__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--spacing-200, 8px) var(--spacing-400, 16px);
}
.scenario-header__facet {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200, 8px);
}
.sh-facet-icon {
  display: inline-flex;
  color: var(--color-text-muted, #737373);
}
.sh-facet-icon .sh-ico {
  width: 16px;
  height: 16px;
}
.sh-facet-txt {
  font-size: 0.875rem;
  font-weight: var(--font-weight-medium, 500);
  color: var(--color-text-primary, #171717);
}
.sh-divider {
  width: 1px;
  align-self: stretch;
  min-height: 20px;
  background: var(--color-border, #e5e5e5);
  flex: none;
}
.sh-facepile {
  gap: var(--spacing-300, 10px);
}
.sh-facepile__dots {
  display: inline-flex;
}
.sh-facepile__dot {
  width: 16px;
  height: 16px;
  border-radius: var(--radius-full, 999px);
  border: 2px solid var(--color-surface, #fff);
}
.sh-facepile__dot + .sh-facepile__dot {
  margin-left: -6px;
}
.sh-priceband {
  gap: var(--spacing-300, 10px);
}
.sh-priceband__label {
  font-size: 0.875rem;
  font-weight: var(--font-weight-medium, 500);
  color: var(--color-text-secondary, #525252);
}
.sh-priceband__track {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200, 8px);
}
.sh-pb-val {
  font-size: 0.875rem;
  font-weight: var(--font-weight-medium, 500);
  color: var(--color-text-primary, #171717);
  font-variant-numeric: tabular-nums;
}
.sh-pb-bar {
  position: relative;
  width: 84px;
  height: 5px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    var(--noria-blue-300, #99c8e0),
    var(--color-primary, #235069)
  );
}
.sh-pb-bar:before,
.sh-pb-bar:after {
  content: "";
  position: absolute;
  top: 50%;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid var(--color-primary, #235069);
  transform: translateY(-50%);
}
.sh-pb-bar:before {
  left: -1px;
}
.sh-pb-bar:after {
  right: -1px;
}
.scenario-header__tabs {
  display: flex;
  gap: var(--spacing-100, 4px);
  border-bottom: 1px solid var(--color-border, #e5e5e5);
  overflow-x: auto;
}
.scenario-header__tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200, 8px);
  height: 44px;
  padding-inline: var(--spacing-400, 16px);
  font-size: var(--type-size-200, 1rem);
  color: var(--color-text-secondary, #525252);
  text-decoration: none;
  white-space: nowrap;
  transition: color 0.15s ease;
}
.scenario-header__tab.is-active {
  color: var(--color-primary, #235069);
  font-weight: var(--font-weight-medium, 500);
}
.scenario-header__tab.is-active:after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--color-primary, #235069);
  border-radius: 2px;
}
.stack {
  --gap: var(--spacing-400, 1rem);
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}
.cluster {
  --gap: var(--spacing-300, 0.75rem);
  --align: center;
  --justify: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: var(--justify);
}
.user-trigger > .esa-icon:last-child {
  flex-shrink: 0;
  color: var(--color-text-muted, #737373);
}
.nav-sublink .esa-icon {
  flex-shrink: 0;
  color: var(--color-text-tertiary, #525252);
  transition: color 0.15s ease;
}
.nav-sublink.active .esa-icon {
  color: var(--_nav-active-color, #235069);
}
.esa-icon {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
  line-height: 1;
  color: inherit;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, var(--icon-size-small, 16px));
}
.esa-icon svg {
  display: block;
  width: var(--_icon-size);
  height: var(--_icon-size);
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
}
.esa-icon--xs {
  --_icon-size: var(--icon-size-xs, 14px);
}

.noria-overview-panel {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400, 16px);
  padding-block-start: var(--spacing-400, 16px);
}
.noria-overview__cards {
  --grid-min: 22rem;
}
.esa-card {
  --_card-bg: var(--card-bg, var(--color-surface, #ffffff));
  --_card-border: var(--card-border-color, var(--color-border, #e5e5e5));
  --_card-radius: var(--card-radius, var(--radius-300, 0.5rem));
  --_card-padding: var(--card-padding, var(--spacing-500, 1.5rem));
  --_card-header-bg: var(--card-header-bg, transparent);
  --_card-header-color: var(--card-header-color, var(--color-text-primary, #171717));
  --_card-header-border: var(
    --card-header-border-color,
    var(--color-border-light, #efefef)
  );
  display: block;
  background: var(--_card-bg);
  border: 1px solid var(--_card-border);
  border-radius: var(--_card-radius);
  overflow: hidden;
}
.esa-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-400, 1rem) var(--_card-padding);
  background: var(--_card-header-bg);
  color: var(--_card-header-color);
  border-bottom: 1px solid var(--_card-header-border);
  min-height: 56px;
}
.esa-card__header-content {
  display: flex;
  align-items: center;
  gap: var(--spacing-300, 0.75rem);
}
.esa-card__titles {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-050, 0.125rem);
}
.esa-card__title {
  font-size: var(--type-size-250, 1.0625rem);
  font-weight: 600;
  margin: 0;
  color: inherit;
  font-family: var(--font-sans, "DM Sans", sans-serif);
}
.esa-card__actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-200, 0.5rem);
}
.esa-card__body {
  padding: var(--_card-padding);
}
.noria-kv {
  margin: 0;
}
.noria-kv__row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--spacing-400, 16px);
  padding: var(--spacing-300, 12px) 0;
  border-bottom: 1px solid var(--color-border, #e5e5e5);
}
.noria-kv__row:first-child {
